		// ----------------------------------------------------------------
		// FindSection
		// ----------------------------------------------------------------

		bool FindSection(const HMODULE hModule, const std::array<const unsigned char, 8>& arrSectionName, void** pAddress, size_t* pSize) noexcept {
			if (!hModule) {
				return false;
			}

			const auto& pDH = reinterpret_cast<PIMAGE_DOS_HEADER>(hModule);
			const auto& pNTHs = reinterpret_cast<PIMAGE_NT_HEADERS>(reinterpret_cast<char*>(hModule) + pDH->e_lfanew);
			const auto& pFH = &(pNTHs->FileHeader);
			const auto& pOH = &(pNTHs->OptionalHeader);

			const auto& pFirstSection = reinterpret_cast<PIMAGE_SECTION_HEADER>(reinterpret_cast<char*>(pOH) + pFH->SizeOfOptionalHeader);
			const WORD unNumberOfSections = pFH->NumberOfSections;
			const size_t unFileAlignment = static_cast<size_t>(pOH->FileAlignment);
			for (WORD unIndex = 0; unIndex < unNumberOfSections; ++unIndex) {
				if (memcmp(arrSectionName.data(), pFirstSection[unIndex].Name, 8) == 0) {
					if (pAddress) {
						*pAddress = reinterpret_cast<void*>(reinterpret_cast<char*>(hModule) + pFirstSection[unIndex].VirtualAddress);
					}

					if (pSize) {
						*pSize = AlignUp(static_cast<size_t>(pFirstSection[unIndex].SizeOfRawData), unFileAlignment);
					}

					return true;
				}
			}

			return false;
		}

		bool FindSectionA(char const* const szModuleName, const std::array<const unsigned char, 8>& arrSectionName, void** pAddress, size_t* pSize) noexcept {
			if (!szModuleName) {
				return false;
			}

			HMODULE hModule = GetModuleHandleA(szModuleName);
			if (!hModule) {
				return false;
			}

			return FindSection(hModule, arrSectionName, pAddress, pSize);
		}

		bool FindSectionW(wchar_t const* const szModuleName, const std::array<const unsigned char, 8>& arrSectionName, void** pAddress, size_t* pSize) noexcept {
			if (!szModuleName) {
				return false;
			}

			HMODULE hModule = GetModuleHandleW(szModuleName);
			if (!hModule) {
				return false;
			}

			return FindSection(hModule, arrSectionName, pAddress, pSize);
		}

