		// ----------------------------------------------------------------
		// FindSignature (Native)
		// ----------------------------------------------------------------

		void const* FindSignatureNative(void const* const pAddress, const size_t unSize, char const* const szSignature, const unsigned char unIgnoredByte, const size_t unOffset) noexcept {
			if (!pAddress || !unSize || !szSignature) {
				return nullptr;
			}

			const size_t unSignatureLength = strnlen_s(szSignature, 0x1000);
			if (unSignatureLength == 0 || unSize < unSignatureLength) {
				return nullptr;
			}

			unsigned char const* pData = static_cast<unsigned char const*>(pAddress);
			unsigned char const* pSignature = reinterpret_cast<unsigned char const*>(szSignature);

			const size_t unLastBase = unSize - unSignatureLength;
			for (size_t unBase = 0; unBase <= unLastBase; ++unBase) {
				bool bMatched = true;

				for (size_t unIndex = 0; unIndex < unSignatureLength; ++unIndex) {
					const unsigned char unByte = pSignature[unIndex];
					if ((unByte != unIgnoredByte) && (pData[unBase + unIndex] != unByte)) {
						bMatched = false;
						break;
					}
				}

				if (bMatched) {
					return pData + unBase + unOffset;
				}
			}

			return nullptr;
		}

		void const* FindSignatureNative(const HMODULE hModule, char const* const szSignature, const unsigned char unIgnoredByte, const size_t unOffset) noexcept {
			if (!hModule || !szSignature) {
				return nullptr;
			}

			const auto& pDH = reinterpret_cast<PIMAGE_DOS_HEADER>(hModule);
			const auto& pNTHs = reinterpret_cast<PIMAGE_NT_HEADERS>(reinterpret_cast<char*>(hModule) + pDH->e_lfanew);
			const auto& pOH = &(pNTHs->OptionalHeader);

			return FindSignatureNative(reinterpret_cast<void*>(hModule), static_cast<size_t>(pOH->SizeOfImage), szSignature, unIgnoredByte, unOffset);
		}

		void const* FindSignatureNative(const HMODULE hModule, const std::array<const unsigned char, 8>& arrSectionName, char const* const szSignature, const unsigned char unIgnoredByte, const size_t unOffset) noexcept {
			if (!hModule || !szSignature) {
				return nullptr;
			}

			void* pAddress = nullptr;
			size_t unSize = 0;
			if (!FindSection(hModule, arrSectionName, &pAddress, &unSize)) {
				return nullptr;
			}

			return FindSignatureNative(pAddress, unSize, szSignature, unIgnoredByte, unOffset);
		}

