		// ----------------------------------------------------------------
		// FindData (Native)
		// ----------------------------------------------------------------

		void const* FindDataNative(void const* const pAddress, const size_t unSize, unsigned char const* const pData, const size_t unDataSize) noexcept {
			if (!pAddress || !pData || !unDataSize || (unSize < unDataSize)) {
				return nullptr;
			}

			unsigned char const* pSource = static_cast<unsigned char const*>(pAddress);
			const size_t unLastBase = unSize - unDataSize;

			for (size_t unBase = 0; unBase <= unLastBase; ++unBase) {
				bool bMatched = true;

				for (size_t unIndex = 0; unIndex < unDataSize; ++unIndex) {
					if (pSource[unBase + unIndex] != pData[unIndex]) {
						bMatched = false;
						break;
					}
				}

				if (bMatched) {
					return pSource + unBase;
				}
			}

			return nullptr;
		}

		void const* FindDataNative(const HMODULE hModule, unsigned char const* const pData, const size_t unDataSize) noexcept {
			if (!hModule || !pData || !unDataSize) {
				return nullptr;
			}

			const auto& pDH = reinterpret_cast<PIMAGE_DOS_HEADER>(hModule);
			const auto& pNTHs = reinterpret_cast<PIMAGE_NT_HEADERS>(reinterpret_cast<char*>(hModule) + pDH->e_lfanew);
			const auto& pOH = &(pNTHs->OptionalHeader);

			return FindDataNative(reinterpret_cast<void*>(hModule), static_cast<size_t>(pOH->SizeOfImage), pData, unDataSize);
		}

