			if (!m_hSemaphore || (m_hSemaphore == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if (WaitForSingleObject(m_hSemaphore, unMilliseconds) != WAIT_OBJECT_0) {
				return false;
			}

			return true;
