		// SemaphoreServer
		// ----------------------------------------------------------------

		SemaphoreServer::SemaphoreServer(bool bIsGlobal, int nInitialCount, int nMaximumCount) {
			memset(m_szSemaphoreName, 0, sizeof(m_szSemaphoreName));
			m_hSemaphore = nullptr;

			auto pTEB = GetTEB();
			if (!pTEB) {
				return;
			}

			const DWORD unPID = pTEB->ClientId.UniqueProcess & 0xFFFFFFFF;
			const DWORD unTID = pTEB->ClientId.UniqueThread & 0xFFFFFFFF;
			const DWORD64 unCycle = __rdtsc();
			if (_stprintf_s(m_szSemaphoreName, _T("SEMAPHORE:%08X:%08X:%08X%08X"), 0xFFFFFFFF - unPID, 0xFFFFFFFF - unTID, static_cast<DWORD>(unCycle & 0xFFFFFFFF), static_cast<DWORD>((unCycle >> 32) & 0xFFFFFFFF)) == -1) {
				memset(m_szSemaphoreName, 0, sizeof(m_szSemaphoreName));
				return;
			}

			TCHAR szSemaphore[64] {};

			if (bIsGlobal) {
				if (_stprintf_s(szSemaphore, _T("Global\\%s"), m_szSemaphoreName) == -1) {
					memset(m_szSemaphoreName, 0, sizeof(m_szSemaphoreName));
					return;
				}
			} else {
				if (_stprintf_s(szSemaphore, _T("Local\\%s"), m_szSemaphoreName) == -1) {
					memset(m_szSemaphoreName, 0, sizeof(m_szSemaphoreName));
					return;
				}
			}

			m_hSemaphore = CreateSemaphore(nullptr, static_cast<LONG>(nInitialCount), static_cast<LONG>(nMaximumCount), szSemaphore);
		}

		SemaphoreServer::~SemaphoreServer() {
			if (m_hSemaphore && (m_hSemaphore != INVALID_HANDLE_VALUE)) {
				CloseHandle(m_hSemaphore);
			}
		}

		bool SemaphoreServer::GetSemaphoreName(TCHAR szSemaphoreName[64]) {
			if (!m_hSemaphore || (m_hSemaphore == INVALID_HANDLE_VALUE) || !szSemaphoreName) {
				return false;
			}

			memcpy(szSemaphoreName, m_szSemaphoreName, sizeof(m_szSemaphoreName));

			return true;
		}

		HANDLE SemaphoreServer::GetSemaphore() const {
			return m_hSemaphore;
		}

		bool SemaphoreServer::Enter(DWORD unMilliseconds) {
			if (!m_hSemaphore || (m_hSemaphore == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if (WaitForSingleObject(m_hSemaphore, unMilliseconds) != WAIT_OBJECT_0) {
				return false;
			}

			return true;
		}

		bool SemaphoreServer::Leave(int nReleaseCount) {
			if (!m_hSemaphore || (m_hSemaphore == INVALID_HANDLE_VALUE)) {
				return false;
			}

			if (!ReleaseSemaphore(m_hSemaphore, static_cast<LONG>(nReleaseCount), nullptr)) {
				return false;
			}

			return true;
		}

