		// ----------------------------------------------------------------
		// Suspender
		// ----------------------------------------------------------------

		Suspender::Suspender() {
			m_unSuspendDepth = 0;
		}

		Suspender::~Suspender() {
			if (m_Mutex.Lock()) {
				if (m_unSuspendDepth > 0) {
					m_unSuspendDepth = 1;
				}

				m_Mutex.UnLock();
			}

			Resume();
		}

		bool Suspender::Suspend(bool bSweepThreads) {
			if (!m_Mutex.Lock()) {
				return false;
			}

			if (m_unSuspendDepth > 0) {
				++m_unSuspendDepth;
				m_Mutex.UnLock();
				return true;
			}

			HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD, 0);
			if (!hSnap || (hSnap == INVALID_HANDLE_VALUE)) {
				m_Mutex.UnLock();
				return false;
			}

			THREADENTRY32 te {};
			te.dwSize = sizeof(THREADENTRY32);

			if (!Thread32First(hSnap, &te)) {
				CloseHandle(hSnap);
				m_Mutex.UnLock();
				return false;
			}

			const auto& pTEB = GetTEB();
			if (!pTEB) {
				CloseHandle(hSnap);
				m_Mutex.UnLock();
				return false;
			}

			m_setSuspendedTIDs.clear();

			do {
				if ((pTEB->ClientId.UniqueProcess == te.th32OwnerProcessID) && (pTEB->ClientId.UniqueThread != te.th32ThreadID)) {
					HANDLE hThread = OpenThread(THREAD_QUERY_LIMITED_INFORMATION | THREAD_SUSPEND_RESUME | THREAD_GET_CONTEXT | THREAD_SET_CONTEXT, FALSE, te.th32ThreadID);
					if (hThread && (hThread != INVALID_HANDLE_VALUE)) {
						if (SuspendThread(hThread) == static_cast<DWORD>(-1)) {
							CloseHandle(hThread);
							continue;
						}

						CONTEXT ctx {};
						ctx.ContextFlags = CONTEXT_FULL;
						if (!GetThreadContext(hThread, &ctx)) {
							ResumeThread(hThread);
							CloseHandle(hThread);
							continue;
						}

						m_vecThreads.emplace_back(te.th32ThreadID, hThread, ctx);
						m_setSuspendedTIDs.insert(te.th32ThreadID);
					}
				}
			} while (Thread32Next(hSnap, &te));

			CloseHandle(hSnap);

			if (bSweepThreads) {
				const DWORD64 unStartTick = GetTickCount64();

				while (true) {
					Sleep(25);

					const size_t unAdded = SuspendNewThreadsSnapshot();
					if (unAdded == 0) {
						break;
					}

					if ((GetTickCount64() - unStartTick) >= 100) {
						break;
					}
				}
			}

			m_unSuspendDepth = 1;
			m_Mutex.UnLock();
			return true;
		}

		void Suspender::Resume() {
			if (!m_Mutex.Lock()) {
				return;
			}

			if (m_unSuspendDepth == 0) {
				m_Mutex.UnLock();
				return;
			}

			if (--m_unSuspendDepth > 0) {
				m_Mutex.UnLock();
				return;
			}

			for (auto& thread : m_vecThreads) {
				SetThreadContext(thread.m_hHandle, &thread.m_CTX);
				ResumeThread(thread.m_hHandle);
				CloseHandle(thread.m_hHandle);
			}

			m_vecThreads.clear();
			m_setSuspendedTIDs.clear();

			m_Mutex.UnLock();
		}

		bool Suspender::IsSuspended() {
			if (!m_Mutex.Lock()) {
				return false;
			}

			const bool bSuspended = m_unSuspendDepth > 0;
			m_Mutex.UnLock();
			return bSuspended;
		}

		size_t Suspender::GetSuspendDepth() {
			if (!m_Mutex.Lock()) {
				return 0;
			}

			const size_t unDepth = m_unSuspendDepth;
			m_Mutex.UnLock();
			return unDepth;
		}

		bool Suspender::IsRegionExecuting(void* pAddress, size_t unSize) {
			if (!pAddress || !unSize) {
				return false;
			}

			for (auto& thread : m_vecThreads) {
#if defined(DETOURS_ARCH_X64)
				void* pIP = reinterpret_cast<void*>(thread.m_CTX.Rip);
#elif defined(DETOURS_ARCH_X86)
				void* pIP = reinterpret_cast<void*>(thread.m_CTX.Eip);
#endif
				if ((pIP >= pAddress) && (pIP < (reinterpret_cast<char*>(pAddress) + unSize))) {
					return true;
				}
			}

			return false;
		}

		bool Suspender::IsRegionInCallStacks(void* pAddress, size_t unSize) {
			if (!pAddress || !unSize) {
				return false;
			}

			for (auto& thread : m_vecThreads) {
				auto vecShadowCallStack = GetShadowCallStack(thread.m_hHandle);
				for (const auto& ReturnAddress : vecShadowCallStack) {
					if ((ReturnAddress >= pAddress) && (ReturnAddress < (reinterpret_cast<char*>(pAddress) + unSize))) {
						return true;
					}
				}

				if (vecShadowCallStack.empty()) {
					auto vecCallStack = GetCallStack(thread.m_hHandle);
					for (const auto& ReturnAddress : vecCallStack) {
						if ((ReturnAddress >= pAddress) && (ReturnAddress < (reinterpret_cast<char*>(pAddress) + unSize))) {
							return true;
						}
					}
				}
			}

			return false;
		}

		void Suspender::FixExecutionAddress(void* pAddress, void* pNewAddress) {
			if (!pAddress || !pNewAddress) {
				return;
			}

			for (auto& thread : m_vecThreads) {
#if defined(DETOURS_ARCH_X64)
				DWORD64 unIP = thread.m_CTX.Rip;
#elif defined(DETOURS_ARCH_X86)
				DWORD unIP = thread.m_CTX.Eip;
#endif

				if (reinterpret_cast<void*>(unIP) == pAddress) {
#if defined(DETOURS_ARCH_X64)
					unIP = reinterpret_cast<DWORD64>(pNewAddress);
#elif defined(DETOURS_ARCH_X86)
					unIP = reinterpret_cast<DWORD>(pNewAddress);
#endif
				}

#if defined(DETOURS_ARCH_X64)
				thread.m_CTX.Rip = unIP;
#elif defined(DETOURS_ARCH_X86)
				thread.m_CTX.Eip = unIP;
#endif
			}
		}

		size_t Suspender::SuspendNewThreadsSnapshot() {
			size_t unAdded = 0;

			const auto& pTEB = GetTEB();
			if (!pTEB) {
				return 0;
			}

			HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD, 0);
			if (!hSnap || (hSnap == INVALID_HANDLE_VALUE)) {
				return 0;
			}

			THREADENTRY32 te {};
			te.dwSize = sizeof(THREADENTRY32);

			if (!Thread32First(hSnap, &te)) {
				CloseHandle(hSnap);
				return 0;
			}

			do {
				if ((pTEB->ClientId.UniqueProcess == te.th32OwnerProcessID) && (pTEB->ClientId.UniqueThread != te.th32ThreadID) && (m_setSuspendedTIDs.find(te.th32ThreadID) == m_setSuspendedTIDs.end())) {
					HANDLE hThread = OpenThread(THREAD_QUERY_LIMITED_INFORMATION | THREAD_SUSPEND_RESUME | THREAD_GET_CONTEXT | THREAD_SET_CONTEXT, FALSE, te.th32ThreadID);
					if (!hThread || (hThread == INVALID_HANDLE_VALUE)) {
						continue;
					}

					if (SuspendThread(hThread) == static_cast<DWORD>(-1)) {
						CloseHandle(hThread);
						continue;
					}

					CONTEXT ctx {};
					ctx.ContextFlags = CONTEXT_FULL;
					if (!GetThreadContext(hThread, &ctx)) {
						ResumeThread(hThread);
						CloseHandle(hThread);
						continue;
					}

					m_vecThreads.emplace_back(te.th32ThreadID, hThread, ctx);
					m_setSuspendedTIDs.insert(te.th32ThreadID);
					++unAdded;
				}
			} while (Thread32Next(hSnap, &te));

			CloseHandle(hSnap);
			return unAdded;
		}

		SuspendTransaction::SuspendTransaction(Suspender& SuspenderReference, bool bSweepThreads) {
			m_pSuspender = &SuspenderReference;
			m_unBeginDepth = m_pSuspender ? m_pSuspender->GetSuspendDepth() : 0;
			m_bActive = false;
			m_bActive = m_pSuspender->Suspend(bSweepThreads);
		}

		SuspendTransaction::~SuspendTransaction() {
			End();
		}

		bool SuspendTransaction::Begin(bool bSweepThreads) {
			if (!m_pSuspender || m_bActive) {
				return false;
			}

			m_unBeginDepth = m_pSuspender->GetSuspendDepth();
			m_bActive = m_pSuspender->Suspend(bSweepThreads);
			return m_bActive;
		}

		void SuspendTransaction::End() {
			if (!m_pSuspender || !m_bActive) {
				return;
			}

			if (m_pSuspender->GetSuspendDepth() > m_unBeginDepth) {
				m_pSuspender->Resume();
			}

			m_bActive = false;
		}

		bool SuspendTransaction::IsActive() const {
			return m_bActive;
		}

		SuspendTransaction::operator bool() const {
			return m_bActive;
		}

