		Page* MemoryManager::CreatePage() {
			auto pPage = std::make_unique<Page>();
			if (!pPage) {
				return nullptr;
			}

			Page* pPageResult = pPage.get();
			m_vecPages.emplace_back(std::move(pPage));
			return pPageResult;
		}

		Storage* MemoryManager::CreateStorage(size_t unTotalCapacity, size_t unRegionCapacity) {
			auto pStorage = std::make_unique<Storage>(unTotalCapacity, unRegionCapacity);
			if (!pStorage) {
				return nullptr;
			}

			Storage* pStorageResult = pStorage.get();
			m_vecStorages.emplace_back(std::move(pStorage));
			return pStorageResult;
		}

		bool MemoryManager::DestroyPage(Page* pPage) {
			if (!pPage) {
				return false;
			}

			for (auto it = m_vecPages.begin(); it != m_vecPages.end(); ++it) {
				if (it->get() == pPage) {
					m_vecPages.erase(it);
					return true;
				}
			}

			return false;
		}

		bool MemoryManager::DestroyStorage(Storage* pStorage) {
			if (!pStorage) {
				return false;
			}

			for (auto it = m_vecStorages.begin(); it != m_vecStorages.end(); ++it) {
				if (it->get() == pStorage) {
					m_vecStorages.erase(it);
					return true;
				}
			}

			return false;
		}

		std::unique_ptr<Page> MemoryManager::GetPage(void* pAddress) {
			if (!pAddress) {
				return nullptr;
			}

			PAGE_INFO pi;
			if (!GetPageInfo(pAddress, &pi)) {
				return nullptr;
			}

			return std::make_unique<Page>(pi.m_pBaseAddress, false);
		}

		std::unique_ptr<Region> MemoryManager::GetRegion(void* pAddress) {
			if (!pAddress) {
				return nullptr;
			}

			REGION_INFO ri;
			if (!GetRegionInfo(pAddress, &ri)) {
				return nullptr;
			}

			return std::make_unique<Region>(ri.m_pBaseAddress, false);
		}

		std::vector<Page> MemoryManager::CollectPages(void* pAddress, size_t unSize) {
			std::vector<Page> vecPages;

			if (!pAddress || !unSize) {
				return vecPages;
			}

			auto vecPagesInfo = GetPagesInfo(pAddress, unSize);
			if (vecPagesInfo.empty()) {
				return vecPages;
			}

			vecPages.reserve(vecPagesInfo.size());

			for (auto& PageInfo : vecPagesInfo) {
				vecPages.emplace_back(PageInfo.m_pBaseAddress, true);
			}

			return vecPages;
		}

		std::vector<Region> MemoryManager::CollectRegions(void* pAddress, size_t unSize) {
			std::vector<Region> vecRegions;

			if (!pAddress || !unSize) {
				return vecRegions;
			}

			auto vecRegionsInfo = GetRegionsInfo(pAddress, unSize);
			if (vecRegionsInfo.empty()) {
				return vecRegions;
			}

			vecRegions.reserve(vecRegionsInfo.size());

			for (auto& RegionInfo : vecRegionsInfo) {
				vecRegions.emplace_back(RegionInfo.m_pBaseAddress, true);
			}

			return vecRegions;
		}
